+/** The best supported language for an Accept-Language header, else `fallback`. */
+export function pickLanguage(header, fallback = LANGUAGES[0]) {
+  if (typeof header !== "string" || header.trim() === "") return fallback;
+  const ranges = header
+    .split(",")
+    .map((part, index) => {
+      const [tag, ...attrs] = part.trim().split(";");
+      let q = 1;
+      for (const attr of attrs) {
+        const [k, v] = attr.trim().split("=");
+        if (k.trim().toLowerCase() === "q") {
+          const n = /^\s*(0(\.\d{0,3})?|1(\.0{0,3})?)\s*$/.test(v ?? "") ? Number(v) : 0;
+          q = n;
+        }
+      }
+      return { lang: tag.trim().toLowerCase().split("-")[0], q, index };
+    })
+    .filter((r) => r.lang !== "" && r.q > 0)
+    .sort((a, b) => b.q - a.q || a.index - b.index);
+  for (const r of ranges) {
+    if (r.lang === "*") return fallback;
+    if (LANGUAGES.includes(r.lang)) return r.lang;
+  }
+  return fallback;
+}
